const BAD:f64=-1.0e300;
#[no_mangle]
pub unsafe extern "C" fn jaro_similarity(v:*const i64,n:usize)->f64{if v.is_null()||n<2||n>66{return BAD}let a=std::slice::from_raw_parts(v,n);let n1=a[0];if n1<0||n1>32||1+n1 as usize>=n{return BAD}let p=1+n1 as usize;let n2=a[p];if n2<0||n2>32||n1<n2||n!=p+1+n2 as usize{return BAD}let s1=&a[1..p];let s2=&a[p+1..];if s1.iter().chain(s2).any(|&x|!(0..=127).contains(&x)){return BAD}if s1==s2{return 1.0}if n2==0{return 0.0}let radius=std::cmp::max(n1 as usize/2,1)-1;let mut m1=[false;32];let mut m2=[false;32];let mut matches=0;for i in 0..n1 as usize{let start=i.saturating_sub(radius);let end=std::cmp::min(i+radius,n2 as usize-1);for j in start..=end{if s1[i]==s2[j]&&!m2[j]{matches+=1;m1[i]=true;m2[j]=true;break}}}if matches==0{return 0.0}let mut trans=0;let mut j=0;for i in 0..n1 as usize{if m1[i]{while !m2[j]{j+=1}if s1[i]!=s2[j]{trans+=1}j+=1}}trans/=2;((matches as f64/n1 as f64)+(matches as f64/n2 as f64)+((matches-trans)as f64/matches as f64))/3.0}
